body.script:
(() => {
  const XHTML = 'http://www.w3.org/1999/xhtml';
  const body = document.querySelector('body');
  if (!body) return;
  const svgRoot = document.documentElement;
  const htmlRoot = body.parentElement && body.parentElement.namespaceURI === XHTML ? body.parentElement : body;
  const originalCreateElement = document.createElement.bind(document);
  try { Object.defineProperty(document, 'head', { configurable:true, get() { return body; } }); } catch (_) {}
  try { Object.defineProperty(document, 'body', { configurable:true, get() { return body; } }); } catch (_) {}
  try { Object.defineProperty(document, 'documentElement', { configurable:true, get() { return htmlRoot; } }); } catch (_) {}
  document.createElement = function (tag, options) {
    return typeof tag === 'string' ? document.createElementNS(XHTML, tag, options) : originalCreateElement(tag, options);
  };
  const params = new URLSearchParams(location.search);
  const defaultCdn = 'https://cdn.jsdelivr.net/gh/ejgavin/Nexus@main/nexus-svg-cdn-experimental';
  const cdn = (params.get('cdn') || defaultCdn).replace(/\/+$/, '');
  const revision = params.get('rev') || 'svg-v1';
  window.__NEXUS_SVG__ = { cdn, revision };
  const css = document.createElement('link');
  css.rel = 'stylesheet';
  css.href = cdn + '/nexus-svg.css?rev=' + encodeURIComponent(revision);
  body.prepend(css);
  const script = document.createElement('script');
  script.src = cdn + '/nexus-svg-runtime.js?rev=' + encodeURIComponent(revision);
  script.async = false;
  body.appendChild(script);
})();
